(function(){'use strict';document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.ecs-preview-btn').forEach(function(btn){btn.addEventListener('click',function(e){e.stopPropagation();var wrap=btn.closest('.ecs-preview-wrap');var isOpen=wrap.classList.contains('is-open');document.querySelectorAll('.ecs-preview-wrap.is-open').forEach(function(w){w.classList.remove('is-open');w.querySelector('.ecs-preview-btn').classList.remove('is-active');});if(!isOpen){wrap.classList.add('is-open');btn.classList.add('is-active');}});});document.addEventListener('click',function(){document.querySelectorAll('.ecs-preview-wrap.is-open').forEach(function(w){w.classList.remove('is-open');w.querySelector('.ecs-preview-btn').classList.remove('is-active');});});});})();